'AC-reconciliation.1803.1 AC-reconciliation.1803.2 AC18.3.2 AC18.3.3 EPIC-018'; from dataclasses import replace; from datetime import date; from decimal import Decimal; from unittest.mock import AsyncMock, patch; from uuid import uuid4; from src.extraction.orm.layer2 import AtomicTransaction; from src.ledger import Direction, JournalEntry, JournalLine; from src.reconciliation import DEFAULT_CONFIG, score_single, weighted_total
def _hybrid_band_txn_and_entry() -> tuple[AtomicTransaction, JournalEntry]: txn = AtomicTransaction(description='ZQXW MERCHANT PURCHASE', amount=Decimal('100.00'), txn_date=date(2024, 1, 1), direction='IN', currency='SGD'); entry = JournalEntry(memo='', entry_date=date(2024, 1, 1), lines=[JournalLine(amount=Decimal('100.00'), direction=Direction.DEBIT)]); return (txn, entry)
async def test_score_single_applies_hybrid_ai_scoring(db) -> None:
    'AC-reconciliation.1803.1 AC18.3.2 EPIC-018'; txn, entry = _hybrid_band_txn_and_entry(); config = replace(DEFAULT_CONFIG, enable_ai_reconciliation=True); pre_ai_total = weighted_total({'amount': 100.0, 'date': 100.0, 'description': 0.0, 'business': 40.0, 'history': 0.0}, DEFAULT_CONFIG); assert pre_ai_total == 69; assert 60 <= pre_ai_total <= 84, 'fixture must land in the hybrid review band'; mock_ai_score = AsyncMock(return_value=90)
    with patch('src.reconciliation.extension.matching.ai_semantic_score', mock_ai_score): candidate = await score_single(db, txn, [entry], config, uuid4(), history_score=0.0)
    expected_score = int(round(Decimal('0.7') * pre_ai_total + Decimal('0.3') * 90, 0)); assert expected_score == 75; assert candidate.score == expected_score; assert candidate.breakdown['hybrid_applied'] == 1.0; assert candidate.breakdown['ai_semantic'] == 90.0; mock_ai_score.assert_awaited_once()
async def test_score_single_flag_off_skips_ai_scoring(db) -> None:
    'AC-reconciliation.1803.2 AC18.3.3 EPIC-018'; txn, entry = _hybrid_band_txn_and_entry(); config = replace(DEFAULT_CONFIG, enable_ai_reconciliation=False); mock_ai_score = AsyncMock(return_value=90)
    with patch('src.reconciliation.extension.matching.ai_semantic_score', mock_ai_score): candidate = await score_single(db, txn, [entry], config, uuid4(), history_score=0.0); mock_ai_score.assert_not_called()
    assert candidate.score == 69; assert 'hybrid_applied' not in candidate.breakdown; assert 'ai_semantic' not in candidate.breakdown
async def test_AC_reconciliation_1803_3_execute_matching_uses_per_user_ai_reconciliation_override(db, test_user, monkeypatch) -> None:
    'AC-reconciliation.1803.3'; from dataclasses import replace; from src.audit import Money; from src.config import settings; from src.extraction.orm.layer2 import TransactionDirection; from src.ledger import Account, AccountType, Entry, post_entry; from src.reconciliation import execute_matching; bank = Account(user_id=test_user.id, name='Checking', type=AccountType.ASSET, currency='SGD'); expense = Account(user_id=test_user.id, name='General Expense', type=AccountType.EXPENSE, currency='SGD'); db.add_all([bank, expense]); await db.flush(); txn_1 = AtomicTransaction(user_id=test_user.id, txn_date=date(2024, 6, 10), description='ZQXW MERCHANT PURCHASE', amount=Decimal('100.00'), direction=TransactionDirection.IN, currency='SGD', dedup_hash='hybrid-override-txn-1', source_documents=[{'doc_id': str(uuid4())}]); db.add(txn_1); await db.flush(); await post_entry(db, user_id=test_user.id, entry_date=date(2024, 6, 10), memo='Unrelated memo', entry=Entry.transfer(debit=bank.id, credit=expense.id, money=Money(Decimal('100.00'), 'SGD')), base_currency='SGD', operation='hybrid-override-fixture-1'); await db.commit(); monkeypatch.setattr(settings, 'enable_ai_reconciliation', False); test_user.ai_settings = {'enable_ai_reconciliation': True}; await db.commit(); mock_ai_on = AsyncMock(return_value=95)
    with patch('src.reconciliation.extension.matching.load_reconciliation_config', return_value=replace(DEFAULT_CONFIG, enable_ai_reconciliation=False)), patch('src.reconciliation.extension.matching.ai_semantic_score', mock_ai_on), patch('src.reconciliation.extension.phases.transfer_detection.detect_transfer_pattern', return_value=False), patch('src.reconciliation.extension.matching.score_pattern', new_callable=AsyncMock, return_value=0.0): matches_on = await execute_matching(db, user_id=test_user.id, currency='SGD')
    assert len(matches_on) == 1; assert matches_on[0].atomic_txn_id == txn_1.id; assert matches_on[0].match_score == 78; assert matches_on[0].score_breakdown.get('hybrid_applied') == 1.0; assert matches_on[0].score_breakdown.get('ai_semantic') == 95.0; mock_ai_on.assert_awaited_once(); txn_2 = AtomicTransaction(user_id=test_user.id, txn_date=date(2024, 6, 20), description='ZQXW MERCHANT PURCHASE', amount=Decimal('200.00'), direction=TransactionDirection.IN, currency='SGD', dedup_hash='hybrid-override-txn-2', source_documents=[{'doc_id': str(uuid4())}]); db.add(txn_2); await db.flush(); await post_entry(db, user_id=test_user.id, entry_date=date(2024, 6, 20), memo='Unrelated memo', entry=Entry.transfer(debit=bank.id, credit=expense.id, money=Money(Decimal('200.00'), 'SGD')), base_currency='SGD', operation='hybrid-override-fixture-2'); monkeypatch.setattr(settings, 'enable_ai_reconciliation', True); test_user.ai_settings = {'enable_ai_reconciliation': False}; await db.commit(); mock_ai_off = AsyncMock(return_value=95)
    with patch('src.reconciliation.extension.matching.load_reconciliation_config', return_value=replace(DEFAULT_CONFIG, enable_ai_reconciliation=True)), patch('src.reconciliation.extension.matching.ai_semantic_score', mock_ai_off), patch('src.reconciliation.extension.phases.transfer_detection.detect_transfer_pattern', return_value=False), patch('src.reconciliation.extension.matching.score_pattern', new_callable=AsyncMock, return_value=0.0): matches_off = await execute_matching(db, user_id=test_user.id, currency='SGD')
    assert len(matches_off) == 1; assert matches_off[0].atomic_txn_id == txn_2.id; assert matches_off[0].match_score == 71; assert 'hybrid_applied' not in matches_off[0].score_breakdown; assert 'ai_semantic' not in matches_off[0].score_breakdown; mock_ai_off.assert_not_called()
